package br.edu.psei;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.net.Uri;import android.widget.*;import android.view.*;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
public class MainActivity extends Activity {
 EditText ins,nome,curso,banca,obs; EditText[] notas=new EditText[3]; TextView status; CheckBox ciencia; MediaRecorder rec; MediaPlayer player; File audio; boolean paused; String id; File dir; final String[] criterios={"Comunicação oral em português","Capacidade argumentativa","Interesse acadêmico"}; final double[] max={2,5,3};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);dir=new File(getFilesDir(),"entrevistas");dir.mkdirs();ScrollView s=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,40,24,24);s.addView(l);setContentView(s);TextView t=new TextView(this);t.setText("UFOPA | PSEI 2027\nEntrevistas — versão experimental");t.setTextSize(24);t.setTextColor(0xff174a78);l.addView(t);ins=field(l,"Inscrição");nome=field(l,"Nome");curso=field(l,"Curso");banca=field(l,"Banca");ciencia=new CheckBox(this);ciencia.setText("Ciência sobre gravação registrada");l.addView(ciencia);status=new TextView(this);l.addView(status);button(l,"Gravar entrevista",()->start(false));button(l,"Testar microfone (5 segundos)",()->start(true));button(l,"Pausar / retomar",()->toggle());button(l,"Encerrar gravação",()->stop());button(l,"Reproduzir áudio",()->play());button(l,"Importar áudio externo",()->{if(rec!=null)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("audio/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,2);});for(int j=0;j<3;j++){notas[j]=field(l,criterios[j]+" (0 a "+max[j]+")");notas[j].setInputType(8194);}obs=field(l,"Observações / fundamentação (opcional)");button(l,"Salvar avaliação",()->save());button(l,"Consultar registros",()->list());button(l,"Nova ficha",()->{if(rec!=null)return;new AlertDialog.Builder(this).setMessage("Abrir nova ficha? Salve a atual antes.").setPositiveButton("Sim",(a,z)->clear()).setNegativeButton("Cancelar",null).show();});button(l,"Exportar ZIP para comissão",()->{if(rec!=null)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"PSEI_entrevistas.zip");startActivityForResult(i,3);});clear();}
 EditText field(LinearLayout l,String h){TextView t=new TextView(this);t.setText(h);l.addView(t);EditText e=new EditText(this);l.addView(e);return e;} void button(LinearLayout l,String n,Runnable r){Button b=new Button(this);b.setText(n);l.addView(b);b.setOnClickListener(v->r.run());} void msg(String s){status.setText(s);Toast.makeText(this,s,Toast.LENGTH_LONG).show();} String val(EditText e){return e.getText().toString().trim();}
 void clear(){id=UUID.randomUUID().toString();audio=null;for(EditText e:new EditText[]{ins,nome,curso,banca,obs,notas[0],notas[1],notas[2]})e.setText("");ciencia.setChecked(false);status.setText("Aguardando");}
 void start(boolean test){if(rec!=null)return;if(!test&&(val(ins).isEmpty()||val(nome).isEmpty()||!ciencia.isChecked())){msg("Informe inscrição, nome e ciência.");return;}if(!test&&audio!=null){msg("Já existe áudio nesta ficha.");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},1);msg("Autorize e tente novamente.");return;}try{File f=new File(dir,id+(test?"-teste":"")+".m4a");rec=new MediaRecorder();rec.setAudioSource(MediaRecorder.AudioSource.MIC);rec.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);rec.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);rec.setOutputFile(f.getPath());rec.prepare();rec.start();paused=false;audio=f;msg("Gravando");if(test)new Handler().postDelayed(()->{stop();play();audio=null;f.delete();},5000);}catch(Exception e){release();msg("Falha: "+e.getMessage());}}
 void toggle(){if(rec==null)return;try{if(paused)rec.resume();else rec.pause();paused=!paused;msg(paused?"Pausado":"Gravando");}catch(Exception e){msg("Falha ao pausar");}} void release(){if(rec!=null){rec.release();rec=null;}} void stop(){if(rec==null)return;try{rec.stop();msg("Gravação encerrada. Confira o áudio.");}catch(Exception e){audio=null;msg("Falha na gravação");}finally{release();}} void play(){if(audio==null||rec!=null)return;try{if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(audio.getPath());player.prepare();player.start();}catch(Exception e){msg("Falha na reprodução");}}
 void save(){if(rec!=null)return;try{if(val(ins).isEmpty()||val(nome).isEmpty())throw new Exception("Informe inscrição e nome");if(audio==null||!audio.exists()||audio.length()==0)throw new Exception("Gravação necessária");JSONObject j=new JSONObject();j.put("inscricao",val(ins));j.put("nome",val(nome));j.put("curso",val(curso));j.put("banca",val(banca));j.put("ciencia",ciencia.isChecked());j.put("observacoes",val(obs));j.put("audio",audio.getName());double total=0;JSONArray a=new JSONArray();for(int k=0;k<3;k++){double n=Double.parseDouble(val(notas[k]).replace(',','.'));if(!Double.isFinite(n)||n<0||n>max[k])throw new Exception("Nota inválida");a.put(n);total+=n;}j.put("notas",a);j.put("total",total);j.put("data",new Date().toString());try(FileOutputStream o=new FileOutputStream(new File(dir,id+".json"))){o.write(j.toString(2).getBytes("UTF-8"));}msg("Avaliação salva. Nota: "+total);}catch(Exception e){msg("Não salvo: "+e.getMessage());}}
 String read(File f)throws Exception{try(InputStream i=new FileInputStream(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){copy(i,o);return o.toString("UTF-8");}} void list(){if(rec!=null)return;File[] fs=dir.listFiles((d,n)->n.endsWith(".json"));if(fs==null)return;ArrayList<String> labels=new ArrayList<>();ArrayList<File> files=new ArrayList<>();for(File f:fs)try{JSONObject j=new JSONObject(read(f));labels.add(j.getString("inscricao")+" — "+j.getString("nome"));files.add(f);}catch(Exception e){}new AlertDialog.Builder(this).setTitle("Entrevistas salvas").setItems(labels.toArray(new String[0]),(a,k)->{try{File f=files.get(k);JSONObject j=new JSONObject(read(f));clear();id=f.getName().replace(".json","");ins.setText(j.getString("inscricao"));nome.setText(j.getString("nome"));curso.setText(j.optString("curso"));banca.setText(j.optString("banca"));obs.setText(j.optString("observacoes"));ciencia.setChecked(j.optBoolean("ciencia"));for(int x=0;x<3;x++)notas[x].setText(j.getJSONArray("notas").getString(x));audio=new File(dir,j.getString("audio"));msg("Registro aberto");}catch(Exception e){msg("Falha ao abrir");}}).show();}
 void copy(InputStream i,OutputStream o)throws IOException{byte[] b=new byte[65536];int n;while((n=i.read(b))!=-1)o.write(b,0,n);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;try{if(r==2){if(audio!=null){msg("Já existe áudio");return;}String type=getContentResolver().getType(d.getData());String ext=type!=null&&type.contains("mpeg")?".mp3":type!=null&&type.contains("wav")?".wav":type!=null&&type.contains("ogg")?".ogg":type!=null&&type.contains("webm")?".webm":".m4a";File f=new File(dir,id+ext);try(InputStream i=getContentResolver().openInputStream(d.getData());OutputStream o=new FileOutputStream(f)){copy(i,o);}audio=f;msg("Áudio importado");}if(r==3){try(ZipOutputStream z=new ZipOutputStream(getContentResolver().openOutputStream(d.getData()))){File[] fs=dir.listFiles((x,n)->n.endsWith(".json"));if(fs!=null)for(File f:fs){JSONObject j=new JSONObject(read(f));for(File item:new File[]{f,new File(dir,j.getString("audio"))}){z.putNextEntry(new ZipEntry(item.getName()));try(InputStream i=new FileInputStream(item)){copy(i,z);}z.closeEntry();}}}msg("ZIP exportado");}}catch(Exception e){msg("Falha: "+e.getMessage());}}
 @Override public void onBackPressed(){if(rec!=null){msg("Encerre a gravação antes de sair.");return;}super.onBackPressed();}
}